import json

import pytest

from video_corpus_miner.stages.ingest import (
    _parse_frame_rate,
    ingest,
    ingest_video,
    parse_probe,
    read_manifest,
)


# --- Real files (generated by the fixtures_dir fixture) ---

def test_valid_video(fixtures_dir):
    record = ingest_video(fixtures_dir / "valid.mp4")
    assert record.status == "ok"
    assert record.error is None
    assert record.has_audio is True
    assert (record.width, record.height) == (64, 64)
    assert record.fps == pytest.approx(10)
    assert record.duration_s == pytest.approx(1, abs=0.1)
    assert len(record.content_hash) == 64


def test_video_without_audio_is_still_ok(fixtures_dir):
    record = ingest_video(fixtures_dir / "no_audio.mp4")
    assert record.status == "ok"
    assert record.has_audio is False


def test_corrupt_file_is_quarantined(fixtures_dir):
    record = ingest_video(fixtures_dir / "corrupt.mp4")
    assert record.status == "quarantined"
    assert record.error.startswith("ffprobe:")
    assert record.content_hash is None


def test_audio_only_file_is_quarantined(fixtures_dir):
    record = ingest_video(fixtures_dir / "audio_only.m4a")
    assert record.status == "quarantined"
    assert record.error == "no video stream"


def test_missing_file_is_quarantined(tmp_path):
    record = ingest_video(tmp_path / "does_not_exist.mp4")
    assert record.status == "quarantined"
    assert record.error == "file not found"


def test_ingest_keeps_going_and_reruns_identically(fixtures_dir, tmp_path):
    manifest = tmp_path / "manifest.json"
    manifest.write_text(json.dumps([
        str(fixtures_dir / "valid.mp4"),
        {"path": str(fixtures_dir / "corrupt.mp4")},
        str(tmp_path / "missing.mp4"),
        str(fixtures_dir / "no_audio.mp4"),
    ]))

    first = tmp_path / "out1.jsonl"
    second = tmp_path / "out2.jsonl"
    records = ingest(manifest, first)
    ingest(manifest, second)

    assert [r.status for r in records] == ["ok", "quarantined", "quarantined", "ok"]
    assert first.read_text() == second.read_text()
    assert len(first.read_text().splitlines()) == 4


# --- Manifest parsing ---

def test_manifest_resolves_relative_paths(tmp_path):
    manifest = tmp_path / "manifest.json"
    manifest.write_text(json.dumps({"files": ["a.mp4", {"path": "sub/b.mp4"}]}))
    assert read_manifest(manifest) == [
        (tmp_path / "a.mp4").resolve(),
        (tmp_path / "sub/b.mp4").resolve(),
    ]


# --- Metadata parsing (no ffmpeg needed) ---

@pytest.mark.parametrize(
    ("rate", "expected"),
    [("30000/1001", 29.97), ("25/1", 25.0), ("0/0", None), ("0/1", None), (None, None), ("junk", None)],
)
def test_parse_frame_rate(rate, expected):
    result = _parse_frame_rate(rate)
    if expected is None:
        assert result is None
    else:
        assert result == pytest.approx(expected, abs=0.01)


def test_parse_probe_finds_video_stream_when_not_first():
    probe = {
        "format": {"duration": "2.5"},
        "streams": [
            {"codec_type": "audio"},
            {"codec_type": "video", "width": 640, "height": 360, "avg_frame_rate": "24/1"},
        ],
    }
    assert parse_probe(probe) == {
        "duration_s": 2.5,
        "fps": 24.0,
        "width": 640,
        "height": 360,
        "has_audio": True,
    }


def test_parse_probe_ignores_cover_art():
    probe = {
        "format": {"duration": "3"},
        "streams": [
            {"codec_type": "audio"},
            {"codec_type": "video", "disposition": {"attached_pic": 1}},
        ],
    }
    with pytest.raises(ValueError, match="no video stream"):
        parse_probe(probe)


def test_parse_probe_falls_back_to_r_frame_rate():
    probe = {
        "format": {"duration": "1"},
        "streams": [{"codec_type": "video", "avg_frame_rate": "0/0", "r_frame_rate": "30/1"}],
    }
    assert parse_probe(probe)["fps"] == 30.0


def test_parse_probe_rejects_missing_duration():
    probe = {"format": {}, "streams": [{"codec_type": "video"}]}
    with pytest.raises(ValueError, match="no duration"):
        parse_probe(probe)
